package com.codeguardian.controller; import com.codeguardian.service.ReportService; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/report") @RequiredArgsConstructor public class ReportController{private final ReportService service;@PostMapping("/{id}") public ResponseEntity<String> generate(@PathVariable Long id){return html(service.generateHTMLReport(id));}@GetMapping("/{id}") public ResponseEntity<String> view(@PathVariable Long id){return html(service.generateHTMLReport(id));}@GetMapping("/history") public org.springframework.data.domain.Page<com.codeguardian.entity.ReviewReport> history(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.history(org.springframework.data.domain.PageRequest.of(page,size));}private ResponseEntity<String> html(String body){return ResponseEntity.ok().contentType(MediaType.TEXT_HTML).body(body);}}
